import crypto from 'crypto'
import bcrypt from 'bcryptjs'
import { db } from './db'

export interface User {
  email: string
  role: 'admin' | 'user'
}

export interface Session {
  id: string
  email: string
  role: 'admin' | 'user'
  expires_at: number
}

export function getUserByEmail(email: string): User | null {
  const user = db.prepare('SELECT email, role FROM users WHERE email = ?').get(email) as any
  if (!user) return null
  return {
    email: user.email,
    role: user.role,
  }
}

export function getAllUsers(): User[] {
  return db.prepare('SELECT email, role FROM users ORDER BY email ASC').all() as any
}

export function verifyUserPassword(email: string, password: string): User | null {
  const user = db.prepare('SELECT email, password_hash, role FROM users WHERE email = ?').get(email) as any
  if (!user) return null
  const match = bcrypt.compareSync(password, user.password_hash)
  if (!match) return null
  return {
    email: user.email,
    role: user.role,
  }
}

export function createSession(email: string, role: string): string {
  const sessionId = crypto.randomUUID()
  const expiresAt = Date.now() + 24 * 60 * 60 * 1000 // 24 hours
  db.prepare('INSERT INTO sessions (id, email, role, expires_at) VALUES (?, ?, ?, ?)').run(
    sessionId,
    email,
    role,
    expiresAt
  )
  return sessionId
}

export function getSession(sessionId: string | undefined): User | null {
  if (!sessionId) return null
  const session = db.prepare('SELECT email, role, expires_at FROM sessions WHERE id = ?').get(sessionId) as any
  if (!session) return null
  if (Date.now() > session.expires_at) {
    db.prepare('DELETE FROM sessions WHERE id = ?').run(sessionId)
    return null
  }
  return {
    email: session.email,
    role: session.role,
  }
}

export function deleteSession(sessionId: string | undefined) {
  if (!sessionId) return
  db.prepare('DELETE FROM sessions WHERE id = ?').run(sessionId)
}

export function updateUserRole(email: string, role: 'admin' | 'user'): boolean {
  const result = db.prepare('UPDATE users SET role = ? WHERE email = ?').run(role, email)
  if (result.changes === 0) {
    return false
  }
  // Also update active sessions so the change takes effect immediately!
  db.prepare('UPDATE sessions SET role = ? WHERE email = ?').run(role, email)
  return true
}

import { getSession, User } from './auth'

export function parseCookies(cookieHeader: string | null): Record<string, string> {
  if (!cookieHeader) return {}
  const cookies: Record<string, string> = {}
  cookieHeader.split(';').forEach(c => {
    const parts = c.split('=')
    if (parts.length >= 2) {
      cookies[parts[0].trim()] = parts.slice(1).join('=').trim()
    }
  })
  return cookies
}

export function getAuthenticatedUserFromRequest(request: Request): User | null {
  const cookieHeader = request.headers.get('cookie')
  const cookies = parseCookies(cookieHeader)
  const sessionId = cookies['rbac_session']
  return getSession(sessionId)
}

export function jsonResponse(data: any, status = 200, headers: HeadersInit = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      'Content-Type': 'application/json',
      ...headers,
    },
  })
}

import { createAPIFileRoute } from '@tanstack/react-start/api'
import { verifyUserPassword, createSession } from '../../auth'
import { jsonResponse } from '../../api-helper'

export const APIRoute = createAPIFileRoute('/api/login')({
  POST: async ({ request }) => {
    try {
      const { email, password } = await request.json() as any
      if (!email || !password) {
        return jsonResponse({ error: 'Email and password are required' }, 401)
      }
      const user = verifyUserPassword(email, password)
      if (!user) {
        return jsonResponse({ error: 'Invalid credentials' }, 401)
      }
      const sessionId = createSession(user.email, user.role)
      return jsonResponse(
        { user: { email: user.email, role: user.role } },
        200,
        {
          'Set-Cookie': `rbac_session=${sessionId}; Path=/; HttpOnly; SameSite=Lax`,
        }
      )
    } catch (err) {
      return jsonResponse({ error: 'Invalid request' }, 401)
    }
  },
})

import { createAPIFileRoute } from '@tanstack/react-start/api'
import { deleteSession } from '../../auth'
import { jsonResponse, parseCookies } from '../../api-helper'

export const APIRoute = createAPIFileRoute('/api/logout')({
  POST: async ({ request }) => {
    const cookieHeader = request.headers.get('cookie')
    const cookies = parseCookies(cookieHeader)
    const sessionId = cookies['rbac_session']
    if (sessionId) {
      deleteSession(sessionId)
    }
    return jsonResponse(
      { ok: true },
      200,
      {
        'Set-Cookie': 'rbac_session=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT',
      }
