export const APIRoute = createAPIFileRoute('/api/admin/users')({
  GET: async ({ request }) => {
    const user = getAuthenticatedUserFromRequest(request)
    if (!user) {
      return jsonResponse({ error: 'Unauthorized' }, 401)
    }
    if (user.role !== 'admin') {
